type Sample = {
  width: number;
  height: number;
  regions: number[][];
  blocks: number[][];
};

/** Geometry is generated by scripts/capture-skeletons.mjs from the real pages.
 * Keep the shared header/footer usable; only the pending page becomes a silhouette.
 */
export function PageSkeleton({ samples, name }: { samples: Sample[]; name: string }) {
  return (
    <div className="page-skeleton" data-skeleton={name}>
      <p role="status" className="sr-only">Loading page. One moment, please.</p>
      <div aria-hidden="true" className="skeleton-canvas">
        {samples.map(sample => (
          <svg key={sample.width} className={`skeleton-sample skeleton-at-${sample.width}`} viewBox={`0 0 ${sample.width} ${sample.height}`} preserveAspectRatio="none" width="100%" height={sample.height} focusable="false">
            {sample.regions.map(([x, y, width, height, tone], i) => <rect key={`r${i}`} x={x} y={y} width={width} height={height} className={`skeleton-surface-${tone}`} />)}
            <g className="skeleton-blocks">
              {sample.blocks.map(([x, y, width, height, tone], i) => <rect key={i} x={x} y={y} width={width} height={height} rx={Math.min(4, height / 2)} className={tone ? "skeleton-block-dark" : "skeleton-block"} />)}
            </g>
          </svg>
        ))}
      </div>
    </div>
  );
}
